INSERT INTO "templates" ("id", "name", "scenario", "body", "type", "status", "created_at", "updated_at") VALUES
  ('v-tp-1', 'Chasing an overdue invoice 1', 'First reminder, friendly', 'Hi [name], hope things are well. Invoice [number] went out on [date] and is now [days] days past due. Could you let me know where it sits in your process?', 'email', 'active', '2026-07-12T15:00:00Z', '2026-07-12T15:00:00Z'),
  ('v-tp-2', 'Meeting follow up 1', 'After a client call', 'Hi [name], thanks for the time today. Here is what I took away. [decisions] I have got [actions] on my side.', 'email', 'active', '2025-09-13T15:00:00Z', '2025-09-13T15:00:00Z'),
